oss brace "+side,new Vector3(side*5,0,-3),new Vector3(side*4,7,-1.8f),.18f,steel);}FieldGoalModels.Cylinder(mechanism,"Visible boot pivot axle",new Vector3(-4.5f,8.5f,-1.8f),new Vector3(4.5f,8.5f,-1.8f),.28f,steel);var coil=new GameObject("Installed cable reel flywheel").transform;coil.SetParent(mechanism,false);coil.localPosition=new Vector3(-4,7.8f,-1.8f);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(coil,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_CableReel01 Variant.prefab",Vector3.one*2,0);actuator.ResetBoot();boot.SetActive(false);mechanism.gameObject.SetActive(false);for(int side=-1;side<=1;side+=2)SportsEventAuthoring.Box("Painted boot strike alignment",new Vector3(side*2.8f,.02f,0),new Vector3(.13f,.02f,5),gold).SetActive(false);
