 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<FieldGoalMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<FieldGoalMatch>();}if(m==null||m.OptionCount!=2||m.endZone==null||m.weatherPresets==null||((CapsuleCollider)m.football.shape).direction!=1||m.truckFlight==null||m.football==null||m.boot==null||!m.boot.strike.isTrigger||m.ground==null||m.posts.childCount<5||m.replay.sources.Length!=3||m.practiceDistanceText==null||m.practiceRetry==null||m.flightWind.clip==null)throw new Exception("Field goal scene references incomplete");Debug.Log("FIELD_GOAL_NATIVE_SCENE_VALIDATED");}
